-- Douro Cellars scenario tables for a Fabric Warehouse (no Spark needed).
-- Run in the Warehouse SQL editor, then add the Warehouse as a source of the Fabric data agent.

DROP TABLE IF EXISTS dbo.customers;
CREATE TABLE dbo.customers (customer_id VARCHAR(10), name VARCHAR(100), country VARCHAR(50), city VARCHAR(50), segment VARCHAR(20), account_owner VARCHAR(50), buyer_name VARCHAR(50), buyer_email VARCHAR(100), top_sku VARCHAR(20), annual_revenue_eur INT, standard_lead_time_days INT);

DROP TABLE IF EXISTS dbo.orders;
CREATE TABLE dbo.orders (order_id VARCHAR(20), customer_id VARCHAR(10), order_date DATE, sku VARCHAR(20), cases INT, value_eur INT, requested_delivery_date DATE, status VARCHAR(20));

DROP TABLE IF EXISTS dbo.shipments;
CREATE TABLE dbo.shipments (shipment_id VARCHAR(20), order_id VARCHAR(20), customer_id VARCHAR(10), carrier VARCHAR(50), ship_date DATE, promised_date DATE, delivered_date DATE, eta DATE, status VARCHAR(20), delay_days INT, delay_reason VARCHAR(200));

DROP TABLE IF EXISTS dbo.inventory;
CREATE TABLE dbo.inventory (sku VARCHAR(20), product_name VARCHAR(100), warehouse VARCHAR(50), on_hand_cases INT, open_order_demand_cases INT, projected_balance_cases INT, reorder_point_cases INT, weekly_demand_cases INT, next_replenishment_date DATE, next_replenishment_cases INT, unit_price_eur_per_case INT);

SELECT 'customers' AS t, COUNT(*) AS n FROM dbo.customers UNION ALL SELECT 'orders', COUNT(*) FROM dbo.orders UNION ALL SELECT 'shipments', COUNT(*) FROM dbo.shipments UNION ALL SELECT 'inventory', COUNT(*) FROM dbo.inventory;